INSERT INTO tasks(lesson_id, title, statement_md, starter_code, solution_code, difficulty, xp_reward, topic, language, source_policy, is_published)
SELECT lr.lesson_id, ts.title, ts.statement_md, ts.starter_code, ts.solution_code, ts.difficulty, ts.xp_reward, ts.topic, ts.language, ts.source_policy, TRUE
FROM lesson_ref lr
CROSS JOIN task_seed ts
ON CONFLICT (lesson_id, title) DO UPDATE
SET statement_md = EXCLUDED.statement_md,
    starter_code = EXCLUDED.starter_code,
    solution_code = EXCLUDED.solution_code,
    difficulty = EXCLUDED.difficulty,
    xp_reward = EXCLUDED.xp_reward,
    topic = EXCLUDED.topic,
    language = EXCLUDED.language,
    source_policy = EXCLUDED.source_policy,
    is_published = TRUE,
    updated_at = NOW();

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 1 AND l.position = 31
)
DELETE FROM task_test_cases tc
USING tasks t, lesson_ref lr
WHERE tc.task_id = t.id
  AND t.lesson_id = lr.lesson_id
  AND t.is_published = TRUE;
WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 1 AND l.position = 31
), task_ref AS (
  SELECT t.id AS task_id, t.title
  FROM tasks t
  JOIN lesson_ref lr ON lr.lesson_id = t.lesson_id
  WHERE t.is_published = TRUE
), block_seed(position, block_type, title, content_md, task_title, quiz_payload) AS (
  VALUES
  (1, $m1_l31_b1_type$theory$m1_l31_b1_type$, $m1_l31_b1_title$Формат экзамена$m1_l31_b1_title$, $m1_l31_b1_content$### Формат экзамена
Экзамен 1 начинается с наблюдаемого состояния. Сначала посмотри, что есть до действия: файл, команда, таблица, route, контейнер, session или внешний ответ. Потом выполни одно маленькое действие и сразу проверь, что изменилось. В шаге «Формат экзамена» это важно разобрать медленно: не переходи к большому заданию, пока не можешь назвать вход, действие и итог.

Для урока Экзамен 1 держи в голове домен `python`. Это значит, что пример нужно читать через конкретные слова урока, а не как общий фрагмент: Формат экзамена. Если встречаешь команду, проверь stdout/stderr и exit code; если видишь HTTP, проверь method, path, status и JSON; если работаешь с базой, проверь строки, транзакцию и порядок результата; если это инфраструктура, проверь файл конфигурации и команду запуска.

### Минимальный пример
```python
# m01_l031_ekzamen-1 m01_l031_ekzamen-1_s001_brief
name = input().strip()
if name:
    print(f"Привет, {name}")
else:
    print("Привет")
```

### Что здесь важно
