T = TypeVar("T")

class Result(Generic[T]):
    def __init__(self, value: T | None, error: str | None):
        self.value = value
        self.error = error
    @classmethod
    def ok(cls, value: T):
        return cls(value, None)
    @classmethod
    def fail(cls, error: str):
        return cls(None, error)
