$m2_l24_t5_starter$, $m2_l24_t5_solution$def send_event(client, name):
    return client.post({'event': name})


class FakeClient:
    def __init__(self):
        self.calls = []
    def post(self, payload):
        self.calls.append(payload)
        return {'ok': True}


def test_send_event_payload():
    client = FakeClient()
    assert send_event(client, 'login') == {'ok': True}
    assert client.calls == [{'event': 'login'}]
