$m2_l24_t8_starter$, $m2_l24_t8_solution$import os


def read_mode():
    return os.getenv('APP_MODE', 'dev')


def test_read_mode(monkeypatch):
    monkeypatch.setenv('APP_MODE', 'test')
    assert read_mode() == 'test'
