$m2_l29_t7_starter$, $m2_l29_t7_solution$from collections import deque

def window_sums(values, size):
    window = deque()
    total = 0
    result = []
    for value in values:
        window.append(value)
        total += value
        if len(window) > size:
            total -= window.popleft()
        if len(window) == size:
            result.append(total)
    return result
