$m2_l36_t7_starter$, $m2_l36_t7_solution$import asyncio

async def retry_get(client, url, attempts):
    last_error = None
    for _ in range(attempts):
        try:
            return await client.get_text(url)
        except TimeoutError as exc:
            last_error = exc
    raise last_error
