INSERT INTO lessons(module_id, title, content_md, position, is_published)
SELECT mr.module_id, ls.title, ls.content_md, ls.position, TRUE
FROM module_ref mr
CROSS JOIN lesson_seed ls
ON CONFLICT (module_id, position) DO UPDATE
SET title = EXCLUDED.title,
    content_md = EXCLUDED.content_md,
    is_published = TRUE,
    updated_at = NOW();

-- m4_l1: FastAPI: первый API
WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 4 AND l.position = 1
)
UPDATE lesson_blocks lb
SET is_published = FALSE,
    updated_at = NOW()
FROM lesson_ref lr
WHERE lb.lesson_id = lr.lesson_id;

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 4 AND l.position = 1
)
UPDATE tasks t
SET is_published = FALSE,
    updated_at = NOW()
FROM lesson_ref lr
WHERE t.lesson_id = lr.lesson_id;

WITH lesson_ref AS (
  SELECT l.id AS lesson_id
  FROM lessons l
  JOIN modules m ON m.id = l.module_id
  JOIN courses c ON c.id = m.course_id AND c.slug = 'python-zero'
  WHERE m.position = 4 AND l.position = 1
), task_seed(title, statement_md, starter_code, solution_code, difficulty, xp_reward, topic, language, source_policy) AS (
  VALUES
  ($m4_l1_t4_title$GET /health: FastAPI: первый API$m4_l1_t4_title$, $m4_l1_t4_stmt$**Коротко:** реализуй GET /health в уроке FastAPI: первый API.

### Условие
Добавь endpoint `GET /health`. Он должен вернуть HTTP 200. JSON-форма ответа должна совпадать с контрактом урока; ключи из примера не переименовывай.

### Вход
HTTP-запрос `GET /health`. Если в проверке есть request body, опиши его через Pydantic-модель.

### Выход
HTTP 200 и JSON, совместимый с примером `{"status": "ok"}`.

### Что проверить
Сверь method и path буквально. Для ошибки верни HTTPException или валидацию FastAPI, а не строку с текстом ошибки.

