$m4_l4_t4_starter$, $m4_l4_t4_solution$from fastapi import FastAPI

app = FastAPI()

TASKS = [{"id": 1, "done": False}, {"id": 2, "done": True}]

@app.get("/tasks")
def list_tasks(done: bool | None = None):
    if done is None:
        return TASKS
    return [task for task in TASKS if task["done"] is done]
