from pydantic import BaseModel

app = FastAPI()

class CommentIn(BaseModel):
    text: str

class CommentOut(BaseModel):
    id: int
    text: str

@app.post("/comments", status_code=status.HTTP_201_CREATED, response_model=CommentOut)
def comments(payload: CommentIn):
    return {"id": 1, "text": payload.text, "moderation_note": "ok"}
