$m4_l15_t4_starter$, $m4_l15_t4_solution$def m04_l015_database_session_s004_kolonki(session_factory, action):
    session = session_factory()
    try:
        result = action(session)
        session.commit()
        return result
    except Exception:
        session.rollback()
        raise
    finally:
        session.close()
