$m4_l23_t7_starter$, $m4_l23_t7_solution$"""Скрытое решение для 4.23.7: TestClient / PATCH /tasks/{task_id}. Показывает конкретный контракт этого шага."""
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()

class TaskPatch(BaseModel):
    title: str | None = None
    done: bool | None = None

@app.patch('/tasks/{task_id}')
def patch_task(task_id: int, payload: TaskPatch):
    if task_id != 1:
        raise HTTPException(status_code=404, detail='task not found')
    task = {'id': task_id, 'title': 'Buy milk', 'done': False}
    update = payload.model_dump(exclude_unset=True)
    task.update(update)
    return task
