$m4_l27_t6_starter$, $m4_l27_t6_solution$from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()

TASKS = {1: {"id": 1, "title": "Buy milk", "done": False}}

class TaskPatch(BaseModel):
    title: str | None = None
    done: bool | None = None

@app.patch("/tasks/{task_id}")
def update_task(task_id: int, payload: TaskPatch | None = None):
    if task_id not in TASKS:
        raise HTTPException(status_code=404, detail="task not found")
    data = TASKS[task_id].copy()
    if payload is not None:
        if payload.title is not None:
            data["title"] = payload.title
        if payload.done is not None:
            data["done"] = payload.done
    return data
